def run(layer, params, context):
    for path in layer.paths:
        for node in path.nodes:
            node.position=(node.position.x+params['dx'], node.position.y)
    for component in layer.components:
        t=list(component.transform);t[4]+=params['dx'];component.transform=tuple(t)
    for anchor in layer.anchors:
        anchor.position=(anchor.position.x+params['dx'],anchor.position.y)
    layer.width+=params['advance']
    print(context['glyph'],layer.width)

